/* =====================================================
   ROOT VARIABLES - LABEL GENERATION FORM
===================================================== */
:root {
  --font-family: 'Inter', 'Open Sans', system-ui, sans-serif;

  --font-size-header: 22px;
  --font-size-label: 14px;
  --font-size-input: 14px;

  --color-card-bg: rgba(255, 255, 255, 0.96);
  --color-card-border: rgba(255, 255, 255, 0.18);
  --color-card-shadow: rgba(0, 0, 0, 0.35);

  --color-header: #0f172a;
  --color-label: #334155;
  --color-input-border: #cbd5e1;
  --color-focus-border: #6366f1;

  --color-submit-btn-bg: linear-gradient(135deg, #6366f1, #4f46e5);
  --color-submit-btn-text: #ffffff;

  --border-radius-card: 18px;
  --border-radius-input: 12px;

  --submit-btn-height: 52px;
}

/* =====================================================
   PAGE BACKGROUND
===================================================== */
body {
  background: radial-gradient(circle at top, #1f3b44, #0b1f26 70%) !important;
  font-family: var(--font-family);
  min-height: 100vh;
}

/* =====================================================
   BRAND NAME LIVE BACKGROUND (VASA DENTICITY)
===================================================== */
body::before {
  content: "VASA DENTICITY   VASA DENTICITY   VASA DENTICITY   VASA DENTICITY";
  position: fixed;
  top: 22%;
  left: -60%;
  width: 220%;
  font-size: 72px;
  font-weight: 800;
  letter-spacing: 36px;
  color: rgba(255, 255, 255, 0.035);
  white-space: nowrap;
  animation: brandFlow 80s linear infinite;
  pointer-events: none;
  z-index: 0;
}

@keyframes brandFlow {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* =====================================================
   FLOATING GRID PATTERN
===================================================== */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  background-image:
    radial-gradient(circle, rgba(255,255,255,0.05) 1px, transparent 1px);
  background-size: 150px 150px;
  animation: gridMove 50s linear infinite;
  pointer-events: none;
  z-index: 0;
}

@keyframes gridMove {
  from { background-position: 0 0; }
  to { background-position: 300px 300px; }
}

/* =====================================================
   FORM CARD CONTAINER
===================================================== */
.n8n-card {
  background: var(--color-card-bg) !important;
  border-radius: var(--border-radius-card) !important;
  box-shadow: 0px 25px 50px rgba(0, 0, 0, 0.4) !important;
  border: 1px solid var(--color-card-border) !important;
  backdrop-filter: blur(16px) !important;
  animation: fadeUp 0.6s ease;
  position: relative;
  z-index: 10;
  max-width: 500px;
  margin: 40px auto;
  padding: 40px;
}

/* =====================================================
   FORM HEADER & TITLE
===================================================== */
.n8n-form h1 {
  font-weight: 700 !important;
  letter-spacing: -0.4px !important;
  color: var(--color-header) !important;
  font-size: 28px !important;
  margin-bottom: 10px !important;
}

.n8n-form p {
  color: #64748b !important;
  margin-bottom: 30px !important;
}

/* =====================================================
   FIELD LABELS
===================================================== */
label {
  font-weight: 600 !important;
  color: var(--color-label) !important;
  font-size: var(--font-size-label) !important;
  display: block !important;
  margin-bottom: 8px !important;
}

/* =====================================================
   FILE UPLOAD INPUT
===================================================== */
input[type="file"] {
  background: #f8fafc !important;
  border: 2px dashed var(--color-input-border) !important;
  border-radius: var(--border-radius-input) !important;
  padding: 20px !important;
  transition: all 0.3s ease !important;
  cursor: pointer !important;
  width: 100% !important;
  font-size: 14px !important;
  color: #64748b !important;
}

input[type="file"]:hover {
  background: #eef2ff !important;
  border-color: var(--color-focus-border) !important;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1) !important;
}

input[type="file"]::file-selector-button {
  background: var(--color-focus-border) !important;
  color: white !important;
  border: none !important;
  padding: 8px 16px !important;
  border-radius: 8px !important;
  font-weight: 600 !important;
  cursor: pointer !important;
  margin-right: 12px !important;
  transition: all 0.2s ease !important;
}

input[type="file"]::file-selector-button:hover {
  background: #4f46e5 !important;
  transform: translateY(-1px);
}

/* =====================================================
   NUMBER INPUTS (Width & Height)
===================================================== */
input[type="number"] {
  width: 100% !important;
  padding: 12px 16px !important;
  border: 2px solid var(--color-input-border) !important;
  border-radius: var(--border-radius-input) !important;
  background: #f8fafc !important;
  font-size: var(--font-size-input) !important;
  color: var(--color-header) !important;
  transition: all 0.3s ease !important;
  font-weight: 500 !important;
}

input[type="number"]:focus {
  outline: none !important;
  border-color: var(--color-focus-border) !important;
  background: #ffffff !important;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1) !important;
}

/* =====================================================
   FIELD SPACING
===================================================== */
.n8n-form-field {
  margin-bottom: 24px !important;
}

/* =====================================================
   SUBMIT BUTTON
===================================================== */
button[type="submit"] {
  height: var(--submit-btn-height) !important;
  width: 100% !important;
  background: var(--color-submit-btn-bg) !important;
  color: var(--color-submit-btn-text) !important;
  font-weight: 700 !important;
  font-size: 16px !important;
  border-radius: 14px !important;
  border: none !important;
  box-shadow: 0px 12px 30px rgba(79, 70, 229, 0.5) !important;
  transition: all 0.35s ease !important;
  cursor: pointer !important;
  margin-top: 30px !important;
  text-transform: uppercase !important;
  letter-spacing: 0.5px !important;
}

button[type="submit"]:hover {
  transform: translateY(-2px) !important;
  box-shadow: 0px 18px 40px rgba(79, 70, 229, 0.65) !important;
  filter: brightness(1.1);
}

button[type="submit"]::after {
  content: "→";
  margin-left: 8px;
  font-size: 20px;
  display: inline-block;
  transition: transform 0.3s ease;
}

button[type="submit"]:hover::after {
  transform: translateX(6px);
}

button[type="submit"]:active {
  transform: translateY(0) !important;
}

/* =====================================================
   FADE-UP ANIMATION
===================================================== */
@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =====================================================
   MOBILE RESPONSIVE
===================================================== */
@media (max-width: 640px) {
  body::before {
    font-size: 48px;
    letter-spacing: 24px;
  }

  .n8n-card {
    margin: 20px !important;
    padding: 30px 20px !important;
    max-width: 100% !important;
  }

  .n8n-form h1 {
    font-size: 24px !important;
  }

  button[type="submit"] {
    height: 48px !important;
  }
}

/* =====================================================
   LOADING STATE (OPTIONAL)
===================================================== */
button[type="submit"]:disabled {
  opacity: 0.6 !important;
  cursor: not-allowed !important;
  transform: none !important;
}

button[type="submit"]:disabled::after {
  content: "⏳";
  animation: spin 1s linear infinite;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

parameters.jsCode:
// Get parts array safely
const parts = $json.candidates[0].content.parts || [];

let base64Image = null;

// Find whichever part contains inlineData (index 0 or 1)
for (const part of parts) {
  if (part.inlineData) {
    base64Image = part.inlineData;
    break;
  }
}

// If nothing found, throw readable error
if (!base64Image) {
  throw new Error("No inlineData image found in Gemini response");
}

// Return clean output with forced jpeg mimeType
return [
  {
    json: {
      base64Image: base64Image.data,
      mimeType: "image/jpeg"
    }
  }
];

